const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // A large polygon representing a part of southern Siberia.
    const geometry = ee.Geometry.Polygon([
        [
            [90, 50],
            [115, 50],
            [115, 56],
            [90, 56]
        ]
    ]);

    const startDate = '2018-10-14';
    const endDate = '2018-10-29';

    // 2. Data Acquisition
    const collection = ee.ImageCollection('MODIS/061/MOD10A1')
        .select('NDSI_Snow_Cover');

    // Get the image for the start date
    const image1_col = collection.filterDate(startDate, ee.Date(startDate).advance(1, 'day'));

    // Get the image for the end date
    const image2_col = collection.filterDate(endDate, ee.Date(endDate).advance(1, 'day'));

    // 3. Data Validation (Check if images exist)
    const count1 = image1_col.size().getInfo();
    const count2 = image2_col.size().getInfo();

    if (count1 === 0 || count2 === 0) {
        console.log(`Image count on ${startDate}: ${count1}`);
        console.log(`Image count on ${endDate}: ${count2}`);
        console.log("No daily MODIS image found for one or both dates.");
        console.log("A: No");
        return;
    }

    const image1 = image1_col.first();
    const image2 = image2_col.first();

    // 4. Processing & Calculation
    // Create a mask for valid snow cover data (values 0-100 are percent snow).
    // Other values represent cloud, water, no decision, etc.
    const validDataMask = (image) => image.select('NDSI_Snow_Cover').lte(100);

    const image1_masked = image1.updateMask(validDataMask(image1));
    const image2_masked = image2.updateMask(validDataMask(image2));

    const scale = 3000; // Use a coarse scale for this large region to avoid timeout.

    // Calculate the mean snow cover percentage for valid pixels
    const stats1 = image1_masked.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const stats2 = image2_masked.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const mean1 = stats1['NDSI_Snow_Cover_mean'];
    const pixels1 = stats1['NDSI_Snow_Cover_count'];
    const mean2 = stats2['NDSI_Snow_Cover_mean'];
    const pixels2 = stats2['NDSI_Snow_Cover_count'];

    // 5. Validation & Final Answer
    if (pixels1 === 0 || pixels2 === 0) {
        console.log(`Valid pixels on ${startDate}: ${pixels1}`);
        console.log(`Valid pixels on ${endDate}: ${pixels2}`);
        console.log("No valid pixels after cloud/water masking for one or both dates.");
        console.log("C2");
        return;
    }

    if (mean1 === null || mean2 === null) {
        console.log(`Mean value on ${startDate}: ${mean1}`);
        console.log(`Mean value on ${endDate}: ${mean2}`);
        console.log("Calculation resulted in a null value.");
        console.log("C3");
        return;
    }

    console.log(`Date ${startDate} - Mean Snow Cover: ${mean1.toFixed(2)}%, Valid Pixels: ${pixels1}`);
    console.log(`Date ${endDate} - Mean Snow Cover: ${mean2.toFixed(2)}%, Valid Pixels: ${pixels2}`);

    if (mean2 > mean1) {
        console.log("Snow cover increased.");
        console.log("A");
    } else {
        console.log("Snow cover did not increase.");
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
